import { useState } from 'react';
import { JxButton } from '@jinx-ui/react';

interface RegistrationData {
  fullName: string;
  email: string;
  phone: string;
  street: string;
  city: string;
  postalCode: string;
}

interface RegistrationStepFormProps {
  onSubmit: (data: RegistrationData) => void;
}

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const INITIAL_DATA: RegistrationData = {
  fullName: '',
  email: '',
  phone: '',
  street: '',
  city: '',
  postalCode: '',
};

export default function RegistrationStepForm({ onSubmit }: RegistrationStepFormProps) {
  const [activeStep, setActiveStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(INITIAL_DATA);

  const updateField = (field: keyof RegistrationData) => (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    setData((prev) => ({ ...prev, [field]: e.target.value }));
  };

  const isStepValid = (step: number) => {
    if (step === 0) return data.fullName.trim() !== '' && data.email.trim() !== '';
    if (step === 1) return data.street.trim() !== '' && data.city.trim() !== '';
    return true;
  };

  const goBack = () => setActiveStep((s) => Math.max(0, s - 1));
  const goNext = () => setActiveStep((s) => Math.min(STEPS.length - 1, s + 1));
  const isLastStep = activeStep === STEPS.length - 1;

  return (
    <div
      className="jx-card"
      style={{
        maxWidth: 480,
        padding: 'var(--jx-space-6)',
        borderRadius: 'var(--jx-radius-lg)',
        backgroundColor: 'var(--jx-color-bg)',
        border: '1px solid var(--jx-color-border)',
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-6)',
      }}
    >
      <ol
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 'var(--jx-space-2)',
          margin: 0,
          padding: 0,
          listStyle: 'none',
        }}
      >
        {STEPS.map((label, index) => {
          const isActive = index === activeStep;
          const isCompleted = index < activeStep;
          return (
            <li
              key={label}
              style={{ display: 'flex', alignItems: 'center', gap: 'var(--jx-space-2)', flex: 1 }}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--jx-space-2)' }}>
                <span
                  aria-current={isActive ? 'step' : undefined}
                  style={{
                    display: 'inline-flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    width: 'var(--jx-space-7)',
                    height: 'var(--jx-space-7)',
                    borderRadius: 'var(--jx-radius-full)',
                    fontSize: 'var(--jx-font-size-sm)',
                    fontWeight: 'var(--jx-font-weight-medium)',
                    color: isActive || isCompleted ? 'var(--jx-color-primary-fg)' : 'var(--jx-color-fg-muted)',
                    backgroundColor: isActive || isCompleted ? 'var(--jx-color-primary)' : 'var(--jx-color-bg-muted)',
                    border: '1px solid var(--jx-color-border)',
                  }}
                >
                  {index + 1}
                </span>
                <span
                  style={{
                    fontSize: 'var(--jx-font-size-sm)',
                    color: isActive ? 'var(--jx-color-fg)' : 'var(--jx-color-fg-muted)',
                    fontWeight: isActive ? 'var(--jx-font-weight-medium)' : 'var(--jx-font-weight-normal)',
                  }}
                >
                  {label}
                </span>
              </div>
              {index < STEPS.length - 1 && (
                <div
                  style={{
                    flex: 1,
                    height: 1,
                    backgroundColor: isCompleted ? 'var(--jx-color-primary)' : 'var(--jx-color-border)',
                  }}
                />
              )}
            </li>
          );
        })}
      </ol>

      {activeStep === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}>
          <label style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-1)' }}>
            <span className="jx-label">Имя и фамилия</span>
            <input
              className="jx-input"
              type="text"
              value={data.fullName}
              onChange={updateField('fullName')}
              placeholder="Иван Иванов"
            />
          </label>
          <label style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-1)' }}>
            <span className="jx-label">Email</span>
            <input
              className="jx-input"
              type="email"
              value={data.email}
              onChange={updateField('email')}
              placeholder="you@example.com"
            />
          </label>
          <label style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-1)' }}>
            <span className="jx-label">Телефон</span>
            <input
              className="jx-input"
              type="tel"
              value={data.phone}
              onChange={updateField('phone')}
              placeholder="+7 900 000-00-00"
            />
          </label>
        </div>
      )}

      {activeStep === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}>
          <label style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-1)' }}>
            <span className="jx-label">Улица и дом</span>
            <input
              className="jx-input"
              type="text"
              value={data.street}
              onChange={updateField('street')}
              placeholder="ул. Пушкина, д. 10"
            />
          </label>
          <label style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-1)' }}>
            <span className="jx-label">Город</span>
            <input
              className="jx-input"
              type="text"
              value={data.city}
              onChange={updateField('city')}
              placeholder="Москва"
            />
          </label>
          <label style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-1)' }}>
            <span className="jx-label">Индекс</span>
            <input
              className="jx-input"
              type="text"
              value={data.postalCode}
              onChange={updateField('postalCode')}
              placeholder="123456"
            />
          </label>
        </div>
      )}

      {activeStep === 2 && (
        <dl
          style={{
            display: 'grid',
            gridTemplateColumns: 'auto 1fr',
            columnGap: 'var(--jx-space-3)',
            rowGap: 'var(--jx-space-2)',
            margin: 0,
            fontSize: 'var(--jx-font-size-sm)',
          }}
        >
          <dt style={{ color: 'var(--jx-color-fg-muted)' }}>Имя</dt>
          <dd style={{ margin: 0, color: 'var(--jx-color-fg)' }}>{data.fullName || '—'}</dd>
          <dt style={{ color: 'var(--jx-color-fg-muted)' }}>Email</dt>
          <dd style={{ margin: 0, color: 'var(--jx-color-fg)' }}>{data.email || '—'}</dd>
          <dt style={{ color: 'var(--jx-color-fg-muted)' }}>Телефон</dt>
          <dd style={{ margin: 0, color: 'var(--jx-color-fg)' }}>{data.phone || '—'}</dd>
          <dt style={{ color: 'var(--jx-color-fg-muted)' }}>Адрес</dt>
          <dd style={{ margin: 0, color: 'var(--jx-color-fg)' }}>
            {[data.street, data.city, data.postalCode].filter(Boolean).join(', ') || '—'}
          </dd>
        </dl>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-space-3)' }}>
        <JxButton variant="secondary" onClick={goBack} disabled={activeStep === 0}>
          Назад
        </JxButton>
        {isLastStep ? (
          <JxButton variant="primary" onClick={() => onSubmit(data)}>
            Отправить
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={goNext} disabled={!isStepValid(activeStep)}>
            Дальше
          </JxButton>
        )}
      </div>
    </div>
  );
}

